export const AGENT_TEMPLATE: Record<string, string> = {
  "README.md": "# An agent\n\nAn agent is a domain of the composition graph, the programs it may run, where its STATE starts, and how it is shown:\n\n- `agent.json` — its title, domain, programs, the agent that answers in words (`ica`), its tools, look and starting points.\n- `knowledge/index.mts` — its domain: the concepts it answers from (meaning, rules, traps; never numbers).\n- `programs/<name>/` — each program: `manifest.json` (the STATE slice it owns: inputs a person sets, fields it derives),\n  `doc.md` (that STATE in words, for the agent), `server/` (its functions) and `web/` (its view, from @superatom/ui).\n  A program's views are cards in a block by default; `\"ui\": { \"as\": \"ui\" }` in its manifest draws them as an interface of\n  their own — the whole width, laid out by the program (a dashboard). Charts: `EChart` with any ECharts option.\n  Its next moves are **option functions** (`package.options`): each, given the step, offers one move computed from the\n  data — or none (the example's `everyKey` and `largestKey`; docs/program-contract.md \"Options\").\n\nTwo doors, one STATE: a click is an `<Intent>` op; a question in words is answered by the composer from the domain and\nthe programs' docs — markdown with marker lines (the answer, kept as the session's answer.md, its attachments beside\nit) — and may change STATE with the same ops.\n\n`sacli agent init <name>` makes this folder; `sacli agent push <folder>` is the one step that builds it, writes it and\npublishes it — people use it at once (`--draft` to keep it unpublished). docs/program-contract.md says what a program must do.\n",
  "agent.json": "{\n  \"name\": \"example\",\n  \"title\": \"Example\",\n  \"domain\": \"example\",\n  \"programs\": [\"example\"],\n  \"ica\": \"composer\",\n  \"tools\": [\"sources\", \"find-schema\", \"get-schema\", \"query\"],\n  \"icon\": \"lucide:layout-grid\",\n  \"accent\": \"primary\",\n  \"says\": \"What this agent is for, in one line.\",\n  \"start\": { \"example\": { \"filter\": null } },\n  \"starts\": [\n    { \"key\": \"all\", \"label\": \"Every key\", \"says\": \"The whole picture\", \"start\": { \"example\": { \"filter\": null } } }\n  ]\n}\n",
  "knowledge/index.mts": "// The agent's domain as the composition graph imports it (`sacli agent push <folder>` imports it, with the agent's\n// programs and the agent itself). How concepts are written: `composition-graph guide`; check before importing with\n// `composition-graph check knowledge/index.mts`. A concept is what one kind of question needs, in only the sections\n// it needs (entity map, definitions, calculation, rules, method, examples); each thing is said in one concept and the\n// others name it in `uses`. No instance — a name, an id, a number, \"today\" — outside the examples. Its programs say in\n// their doc.md what STATE they take, so a question in words can change STATE the same way a click does.\nimport type { ConceptBody } from '@superatom/composition-graph'\n\ntype Concept = ConceptBody & { name?: string }\n\nexport const settings: { name: string; value: unknown; description: string }[] = []\n\n// A domain's concepts: its own, written here, and — by name alone — the project's default concepts every domain starts\n// with ('answering': how every answer is given; 'own-analysis': finding in the data what the domain does not cover).\n// Those live in the project's graph (each project may edit them); named here, they are used as they are there.\nexport const domains: { name: string; description: string; intents: string[]; capabilities: string[]; concepts: (Concept | string)[]; files: string[]; tools: string[]; settings: string[] }[] = [\n  {\n    name: 'example',\n    description: 'What the agent answers, in one line.',\n    intents: ['the questions it answers, in the words people use'],\n    capabilities: [],\n    tools: ['sources', 'find-schema', 'get-schema', 'query'],\n    files: [],\n    settings: [],\n    concepts: [\n      'answering',\n      {\n        name: 'what-the-entities-are-and-how-they-join', title: 'The entities and how they join', form: 'sections',\n        sections: [{ name: 'entity map', text: 'thing ──1:n── line ──n:1── other thing\\n  key thing_id        key other_id' }],\n      },\n      {\n        name: 'how-the-main-figure-is-worked-out', title: 'How the main figure is worked out', form: 'sections',\n        uses: ['what-the-entities-are-and-how-they-join'],\n        sections: [\n          { name: 'definitions', items: ['figure = what it means, generically, or its formula'] },\n          { name: 'calculation', text: 'line → thing\\nfilter what counts · group by what it is shown by · measure sum(value)' },\n          { name: 'rules', items: ['A column that looks like one thing and is another, and how to read it.'] },\n        ],\n      },\n      'own-analysis',\n    ],\n  },\n]\n",
  "programs/example/doc.md": "# example\n\nWhat it shows, in one line. STATE (`example`):\n\n- *Input:* `filter` — one key, or null for all. Set it (a click or words) and the view is worked out again.\n- *Derived:* `data` — at most 100 rows for the filter in force, with the total and the count from the source, fetched once per filter (`data.basis`).\n\nFunctions:\n- `run` answers from the slice.\n- `row` answers a key clicked in the table: a new block below, the same view narrowed to that key.\n\nOptions (computed at each step, offered only where they hold):\n- `everyKey` — with a filter in force: back to every key, saying how many more there are.\n- `largestKey` — without a filter: the key that carries a third or more of the total, opened.\n",
  "programs/example/manifest.json": "{\n  \"id\": \"prg_example\",\n  \"name\": \"example\",\n  \"version\": 1,\n  \"scope\": \"global\",\n  \"owner\": \"user:you\",\n  \"attachesTo\": \"area.topic\",\n  \"reads\": [\"datasource:SOURCE\"],\n  \"published\": false,\n  \"ui\": { \"blocks\": [\"example\"] },\n  \"package\": {\n    \"owns\": \"example\",\n    \"schema\": { \"filter\": { \"nullable\": \"string\" }, \"data\": { \"nullable\": \"json\" } },\n    \"initial\": { \"filter\": null, \"data\": null },\n    \"reads\": [],\n    \"functions\": [{ \"name\": \"run\", \"produces\": \"view\" }, { \"name\": \"row\", \"produces\": \"view\" }],\n    \"options\": [\"everyKey\", \"largestKey\"],\n    \"commands\": [],\n    \"doc\": \"doc.md\"\n  }\n}\n",
  "programs/example/server/index.ts": "// The program's Node side: its functions. Each gets the whole STATE (frozen) and a context whose set() changes only this\n// program's slice; data comes only through ctx.services.query (the reader's data access is applied for you).\n//\n// STATE is inputs and derived: the person sets the inputs (here `filter`), the program derives the rest. The data is\n// fetched once per input (`data.basis` says for which) and kept in the slice, so a run with nothing new asks nothing.\n// The answer is markdown: a first line `**Title** — _what it says_`, then a marker line per block (:::kpis, :::table…).\n// A table's rowMove makes its rows clickable: a click is a step taken — it opens a new block below, answered by row().\n// At most 100 rows are shown; the total and the count come from the source, never from adding up the rows shown.\n// What a program is given (query, append, who…): the platform's own types (`platform/program` in a cloned project).\nimport type { OptionContext, ProgramContext } from '@superatom/program'\nimport { exampleQuery } from './query.js'\n\ntype Row = { key: string; value: number }\ntype Data = { basis: string | null; rows: Row[]; total: number; count: number }\ntype Slice = { filter: string | null; data: Data | null }\ntype Ctx = ProgramContext<Slice>\n\nasync function fetchData(filter: string | null, ctx: Ctx): Promise<Data> {\n  const { sql, params } = exampleQuery(filter)\n  const got = await ctx.services.query('SOURCE', sql, params)\n  return { basis: filter, rows: got.map((r) => ({ key: String(r.key), value: Number(r.value) })), total: Number(got[0]?.total ?? 0), count: Number(got[0]?.keys ?? 0) }\n}\n\nexport async function run(state: { example: Slice }, ctx: Ctx) {\n  const s = state.example\n  let d = s.data && s.data.basis === s.filter ? s.data : null\n  if (!d) { d = await fetchData(s.filter, ctx); ctx.set({ data: d }) }\n  const blocks = {\n    'example-kpis': { type: 'kpis', items: [\n      { label: 'Total', value: d.total, unit: 'count', hint: s.filter ? `for ${s.filter}` : 'every key' },\n      { label: 'Keys', value: d.count, unit: 'count', hint: d.count > d.rows.length ? `the largest ${d.rows.length} shown` : 'all shown' },\n    ] },\n    'example-table': { type: 'table', title: 'Every key — open one to narrow to it', rowMove: { dim: 'key', key: 'key', label: 'key' },\n      columns: [{ key: 'key', label: 'Key' }, { key: 'value', label: 'Value', unit: 'count' }], rows: d.rows },\n  }\n  return { answer: { markdown: [`**Example** — _${d.count} keys${s.filter ? ` for ${s.filter}` : ''}, ${d.total} in total_`, ':::kpis example-kpis', ':::table example-table'].join('\\n'), blocks } }\n}\n\n// ── Options: the next moves this program offers at a step ───────────────────────────────────────────────────────────\n// Each option is a function, listed in the manifest's `package.options`. It is given the step — the whole STATE (frozen),\n// ctx.context (what the session was started with), ctx.history (its answers down to here) — and services that only\n// read. It works out whether its move makes sense HERE, from what is there, and returns it — a label said from the data,\n// and one of this program's functions to call or ops on its own slice — or null: then nothing is offered. It never does\n// the work itself and changes nothing; it is quick (a time limit applies). A fixed list of moves is not an option.\n\n/** With a filter in force: the way back to every key, saying how much more there is. */\nexport async function everyKey(state: { example: Slice }, ctx: OptionContext) {\n  const s = state.example\n  if (!s.filter || !s.data) return null\n  const { sql, params } = exampleQuery(null)\n  const [all] = await ctx.services.query('SOURCE', sql, params)\n  const more = Number(all?.keys ?? 0) - 1\n  return more > 0 ? { label: `Every key — ${more} more besides ${s.filter}`, ops: [{ op: 'set' as const, path: 'example.filter', value: null }], to: 'current' as const } : null\n}\n\n/** Without a filter: the key that carries most of the total, when one does (a third or more of it). */\nexport function largestKey(state: { example: Slice }) {\n  const d = state.example.data\n  const top = d?.rows[0]\n  if (state.example.filter || !d || !top || !d.total || top.value / d.total < 1 / 3) return null\n  return { label: `${top.key}: ${Math.round((100 * top.value) / d.total)}% of the total`, call: { fn: 'row', params: { row: { key: top.key } } }, to: 'new' as const }\n}\n\n/** A row clicked in the table: the new block below it, narrowed to the row's key (a call does not re-run its own program). */\nexport async function row(state: { example: Slice }, ctx: Ctx) {\n  const key = String(((ctx.params.row ?? {}) as Record<string, unknown>).key ?? '')\n  if (!key) return run(state, ctx)\n  ctx.set({ filter: key })\n  return run({ ...state, example: { ...state.example, filter: key } }, ctx)\n}\n",
  "programs/example/server/query.ts": "// The rule, once, as a query the source runs: the total and the number of keys worked out by the source over every row\n// (window functions run before the limit), at most 100 rows returned.\nexport function exampleQuery(filter: string | null): { sql: string; params: Record<string, unknown> } {\n  return {\n    sql: `SELECT key, SUM(amount) AS value, SUM(SUM(amount)) OVER () AS total, COUNT(*) OVER () AS keys\n          FROM some_table${filter ? ' WHERE key = @filter' : ''}\n          GROUP BY key ORDER BY value DESC LIMIT 100`,\n    params: filter ? { filter } : {},\n  }\n}\n",
  "programs/example/web/index.tsx": "// The program's React side: one export per ui block, named in PascalCase (block \"example\" → Example), drawn with\n// { slice, state }. Controls are <Intent>s (or sendIntent from a form) — the one way a screen changes STATE. A control\n// that filters or drills the same view changes it in place (to=\"current\", the default); one that opens another view or\n// records a decision opens a new block (to=\"new\"). Build from the framework (@superatom/ui): Form, Field, Input,\n// ActionBar, the answer's own blocks for tables and charts — what it lacks goes into the framework, not into one program.\nimport { useRef, useState } from 'react'\nimport { Intent, Form, Field, Input, ActionBar, sendIntent } from '@superatom/ui'\n\ntype Slice = { filter: string | null }\n\nexport function Example({ slice }: { slice?: Slice }) {\n  const box = useRef<HTMLDivElement>(null)\n  const [key, setKey] = useState('')\n  const narrow = () => { if (key.trim() && box.current) { sendIntent(box.current, { ops: [{ op: 'set', path: 'example.filter', value: key.trim() }] }); setKey('') } }\n  return (\n    <div ref={box} className=\"sa-stack\">\n      <Form onSubmit={narrow} actions={<button type=\"submit\" className=\"sa-btn\" disabled={!key.trim()}>Narrow</button>}>\n        <Field label=\"A key\" help=\"the view narrows to it, in place\">\n          <Input id=\"example-key\" value={key} placeholder=\"a key\" onChange={setKey} />\n        </Field>\n      </Form>\n      {slice?.filter && (\n        <ActionBar>\n          <Intent ops={[{ op: 'set', path: 'example.filter', value: null }]} className=\"sa-btn\">Every key</Intent>\n        </ActionBar>\n      )}\n    </div>\n  )\n}\n"
}
